//! Parity tests against the Python compose implementation.
//!
//! The fixtures under `tests/fixtures/expected/` are generated by `tests/fixtures/gen_compose.py`
//! from the synthetic projects in `tests/fixtures/projects/`. Each run is replayed here on a fresh
//! copy of the project, with the same environment, fake instance and fake jobs, and compared:
//! the result (or exception), the commands, the instance events, the messages, the resolved
//! compose config (with key order), its hash, the project environment, the defined pipes, the
//! `explain` text and the files `init` writes.

use std::path::{Path, PathBuf};

use indexmap::IndexMap;
use meerschaum_compose::command::RecordingRunner;
use meerschaum_compose::error::Message;
use meerschaum_compose::ops::{
    InMemoryInstance, InMemoryJobs, InstanceEvent, JobInfo, NoInput, RegisteredPipe,
};
use meerschaum_compose::project::{Host, Session, hash_config};
use meerschaum_compose::subactions::{ComposeArgs, ComposeOutput, Services, compose};
use meerschaum_core::pyfmt::{JsonStyle, json_dumps, py_str};
use meerschaum_core::value::{Map, Value};

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn copy_dir(src: &Path, dst: &Path) {
    std::fs::create_dir_all(dst).unwrap();
    for entry in std::fs::read_dir(src).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name();
        if name == "case.json" || name == "__pycache__" {
            continue;
        }
        let path = entry.path();
        if path.is_dir() {
            copy_dir(&path, &dst.join(&name));
        } else {
            std::fs::copy(&path, dst.join(&name)).unwrap();
        }
    }
}

fn jstr(v: &Value) -> String {
    json_dumps(v, JsonStyle::Compact, false)
}

fn normalize_str(s: &str, reps: &[(String, &str)]) -> String {
    let mut out = s.to_string();
    for (old, new) in reps {
        out = out.replace(old.as_str(), new);
    }
    out
}

fn normalize(v: &Value, reps: &[(String, &str)]) -> Value {
    match v {
        Value::Str(s) => Value::Str(normalize_str(s, reps)),
        Value::List(l) => Value::List(l.iter().map(|x| normalize(x, reps)).collect()),
        Value::Map(m) => Value::Map(
            m.iter()
                .map(|(k, x)| (normalize_str(k, reps), normalize(x, reps)))
                .collect(),
        ),
        other => other.clone(),
    }
}

fn get<'a>(v: &'a Value, key: &str) -> &'a Value {
    static NULL: Value = Value::Null;
    v.get(key).unwrap_or(&NULL)
}

fn strs(v: &Value) -> Vec<String> {
    v.as_list()
        .map(|l| l.iter().map(py_str).collect())
        .unwrap_or_default()
}

/// Messages whose text comes from outside compose (connector construction in the generator
/// process, template evaluation tracebacks) or depends on Python's set ordering.
fn normalize_message(kind: &str, text: &str) -> Option<String> {
    for prefix in [
        "Mismatched values for attribute",
        "Exception when creating connector",
        "Failed to resolve pipe syntax",
        "Invalid keys in config",
        "  Invalid keys in config",
        "No instance connector is available",
    ] {
        if text.starts_with(prefix) {
            return None;
        }
    }
    // The undefined-variables warning lists names in Python's set iteration order.
    if text.contains(" not defined!\n     Using") {
        let (names, rest) = text.split_once(" not defined!").unwrap();
        let mut items: Vec<&str> = names.split('\'').filter(|s| s.starts_with('$')).collect();
        items.sort();
        return Some(format!("{kind}: {}{}", items.join(","), rest));
    }
    Some(format!("{kind}: {text}"))
}

struct RunEnv {
    _tmp: tempfile::TempDir,
    base: PathBuf,
    run_dir: PathBuf,
    copy_dir: PathBuf,
}

fn setup(name: &str, run_ix: usize, case: &Value) -> RunEnv {
    let tmp = tempfile::tempdir().unwrap();
    let base = std::fs::canonicalize(tmp.path()).unwrap();
    for sub in ["host-root", "host-plugins", "home", "venvs", "runs"] {
        std::fs::create_dir_all(base.join(sub)).unwrap();
    }
    if let Some(Value::Map(plugins)) = case.get("host_plugins") {
        for (file, text) in plugins {
            std::fs::write(base.join("host-plugins").join(file), py_str(text)).unwrap();
        }
    }
    let run_dir = base.join("runs").join(run_ix.to_string());
    let copy = run_dir.join(name);
    copy_dir(&fixtures().join("projects").join(name), &copy);
    RunEnv {
        _tmp: tmp,
        base,
        run_dir,
        copy_dir: copy,
    }
}

fn fake_instance(case: &Value, project_dir: &Path) -> InMemoryInstance {
    let mut instance = InMemoryInstance::default();
    if let Some(Value::List(regs)) = case.get("registered") {
        for r in regs {
            instance.pipes.push(RegisteredPipe {
                connector_keys: py_str(get(r, "connector")),
                metric_key: py_str(get(r, "metric")),
                location_key: r.get("location").filter(|v| !v.is_null()).map(py_str),
                instance_keys: py_str(get(r, "instance")),
                id: get(r, "id").as_i64().unwrap(),
                parameters: get(r, "parameters").as_map().cloned().unwrap_or_default(),
            });
        }
    }
    let plugins_dir = project_dir.join("plugins");
    instance.installed_plugins = Some(meerschaum_compose::plugins::plugin_names_in_dirs(&[
        plugins_dir,
    ]));
    instance
}

fn fake_jobs(case: &Value) -> InMemoryJobs {
    let mut jobs = InMemoryJobs::default();
    if let Some(Value::Map(specs)) = case.get("jobs") {
        for (name, spec) in specs {
            let env: IndexMap<String, String> = get(spec, "env")
                .as_map()
                .map(|m| m.iter().map(|(k, v)| (k.clone(), py_str(v))).collect())
                .unwrap_or_default();
            jobs.jobs.insert(
                name.clone(),
                JobInfo {
                    sysargs: strs(get(spec, "sysargs")),
                    env,
                    status: py_str(get(spec, "status")),
                    restart: get(spec, "restart").truthy(),
                },
            );
        }
    }
    jobs
}

fn run_case(name: &str, expected: &Value, run_ix: usize, run: &Value) -> Vec<String> {
    let case = get(expected, "case");
    let env = setup(name, run_ix, case);
    let tmp_str = env.base.to_string_lossy().to_string();
    let base_env: IndexMap<String, String> = get(expected, "base_env")
        .as_map()
        .unwrap()
        .iter()
        .map(|(k, v)| (k.clone(), py_str(v).replace("{TMP}", &tmp_str)))
        .collect();
    let cwd_rel = run
        .get("cwd")
        .map(py_str)
        .unwrap_or_default()
        .replace("{PROJECT}", &env.copy_dir.to_string_lossy())
        .replace("{RUN}", &env.run_dir.to_string_lossy())
        .replace("{TMP}", &tmp_str);
    let cwd = PathBuf::from(cwd_rel);
    let host = Host::new(cwd, base_env).unwrap();

    let flags = get(run, "flags");
    let flag = |k: &str| get(flags, k).truthy();
    let args = ComposeArgs {
        action: strs(get(run, "action")),
        sysargs: strs(get(run, "sysargs")),
        file: run
            .get("file")
            .filter(|v| !v.is_null())
            .map(|v| PathBuf::from(py_str(v))),
        env_file: run
            .get("env_file")
            .filter(|v| !v.is_null())
            .map(|v| PathBuf::from(py_str(v))),
        dry: flag("dry"),
        force: flag("force"),
        presync: flag("presync"),
        no_jobs: flag("no_jobs"),
        isolated: flag("isolated"),
        drop: flag("drop"),
        yes: flag("yes"),
        noask: flag("noask"),
        nopretty: flag("nopretty"),
        debug: flag("debug"),
        width: get(run, "width").as_i64().map(|w| w as usize),
        ..ComposeArgs::default()
    };

    let mut runner = RecordingRunner::default();
    let mut instance = fake_instance(case, &env.copy_dir);
    let mut jobs = fake_jobs(case);
    let mut prompter = NoInput;
    let mut session = Session::default();
    let out: ComposeOutput = compose(
        &host,
        &mut session,
        &args,
        Services {
            runner: &mut runner,
            instance: &mut instance,
            jobs: &mut jobs,
            prompter: &mut prompter,
        },
    );

    let reps: Vec<(String, &str)> = vec![
        (env.copy_dir.to_string_lossy().to_string(), "{PROJECT}"),
        (env.run_dir.to_string_lossy().to_string(), "{RUN}"),
        (tmp_str.clone(), "{TMP}"),
    ];
    let label = format!("{name}/{}", py_str(get(run, "name")));
    let mut failures = Vec::new();
    let mut check = |what: &str, ok: bool, detail: String| {
        if !ok {
            failures.push(format!("[{label}] {what} differs:\n{detail}"));
        }
    };

    // Result or exception.
    match (&out.result, run.get("result"), run.get("error")) {
        (Ok(t), Some(Value::List(r)), _) => {
            let exp_ok = r[0].truthy();
            let exp_msg = normalize_str(&py_str(&r[1]), &[]);
            let got_msg = normalize_str(&t.message, &reps);
            check(
                "result",
                t.success == exp_ok && got_msg == exp_msg,
                format!(
                    "  python: ({exp_ok}, {exp_msg:?})\n  rust:   ({}, {got_msg:?})",
                    t.success
                ),
            );
        }
        (Err(e), _, Some(err)) => {
            let exp_type = py_str(get(err, "type"));
            let exp_msg = py_str(get(err, "message"));
            let got = normalize_str(&e.message, &reps);
            // Python 3.14 appends suggestions ("Did you mean 'dtypes'?") to `TypeError`s.
            check(
                "error",
                e.kind.python_name() == exp_type && exp_msg.starts_with(&got),
                format!(
                    "  python: {exp_type}: {exp_msg:?}\n  rust:   {}: {got:?}",
                    e.kind.python_name()
                ),
            );
        }
        (got, r, e) => check(
            "outcome",
            false,
            format!("  python: result={r:?} error={e:?}\n  rust:   {got:?}"),
        ),
    }

    // OVERLAY (v5, PARITY.md "compose explain is side-effect free"): `explain` no longer
    // initializes the root directory, so the reference's `show version` command and "Initializing
    // Meerschaum root directory" message are not expected.
    let is_explain = strs(get(run, "action"))
        .first()
        .is_some_and(|a| a == "explain");
    // Commands.
    let exp_cmds: Vec<String> = get(run, "commands")
        .as_list()
        .unwrap()
        .iter()
        .filter(|c| {
            let sysargs = strs(get(c, "sysargs"));
            !(is_explain
                && (sysargs.starts_with(&["show".to_string(), "version".to_string()])
                    || sysargs.starts_with(&["install".to_string(), "required".to_string()])))
        })
        .map(|c| {
            format!(
                "{:?} subprocess={} capture={} replace={}",
                strs(get(c, "sysargs")),
                get(c, "subprocess").truthy(),
                get(c, "capture_output").truthy(),
                get(c, "replace").truthy()
            )
        })
        .collect();
    let got_cmds: Vec<String> = out
        .commands
        .iter()
        .map(|c| {
            format!(
                "{:?} subprocess={} capture={} replace={}",
                c.sysargs
                    .iter()
                    .map(|s| normalize_str(s, &reps))
                    .collect::<Vec<_>>(),
                c.subprocess,
                c.capture_output,
                c.replace
            )
        })
        .collect();
    check(
        "commands",
        exp_cmds == got_cmds,
        format!("  python: {exp_cmds:#?}\n  rust:   {got_cmds:#?}"),
    );

    // Instance events.
    let exp_events: Vec<String> = get(run, "events")
        .as_list()
        .unwrap()
        .iter()
        .map(|e| {
            let l = e.as_list().unwrap();
            match py_str(&l[0]).as_str() {
                "edit" => format!("edit {} {}", py_str(&l[1]), jstr(&l[2])),
                _ => format!("delete {}", py_str(&l[1])),
            }
        })
        .collect();
    let got_events: Vec<String> = instance
        .events
        .iter()
        .map(|e| match e {
            InstanceEvent::Edit(p, params) => {
                format!("edit {p} {}", jstr(&Value::Map(params.clone())))
            }
            InstanceEvent::Delete(p) => format!("delete {p}"),
        })
        .collect();
    check(
        "events",
        exp_events == got_events,
        format!("  python: {exp_events:#?}\n  rust:   {got_events:#?}"),
    );

    // Messages.
    let exp_msgs: Vec<String> = get(run, "messages")
        .as_list()
        .unwrap()
        .iter()
        .filter_map(|m| {
            let l = m.as_list().unwrap();
            if is_explain
                && (py_str(&l[1]).starts_with("Initializing Meerschaum root directory")
                    || py_str(&l[1]).starts_with("Installing required packages for plugins"))
            {
                return None;
            }
            normalize_message(&py_str(&l[0]), &py_str(&l[1]))
        })
        .collect();
    let got_msgs: Vec<String> = out
        .messages
        .items
        .iter()
        .filter_map(|m| match m {
            Message::Warn(w) => normalize_message("warn", &normalize_str(w, &reps)),
            Message::Info(i) => normalize_message("info", &normalize_str(i, &reps)),
        })
        .collect();
    check(
        "messages",
        exp_msgs == got_msgs,
        format!("  python: {exp_msgs:#?}\n  rust:   {got_msgs:#?}"),
    );

    // Resolved config (key order included), its hash, the environment.
    let exp_config = get(run, "config");
    let got_config = out
        .project
        .as_ref()
        .map(|p| normalize(&Value::Map(p.config.clone()), &reps))
        .unwrap_or(Value::Null);
    check(
        "config",
        jstr(exp_config) == jstr(&got_config),
        format!(
            "  python: {}\n  rust:   {}",
            jstr(exp_config),
            jstr(&got_config)
        ),
    );
    if let (Value::Map(norm), Value::Str(h)) = (&got_config, get(run, "config_hash_normalized")) {
        let ours = hash_config(norm);
        check(
            "config_hash",
            ours == *h,
            format!("  python: {h}\n  rust:   {ours}"),
        );
    }
    let exp_env = get(run, "env");
    if !exp_env.is_null() {
        let got_env = out
            .project
            .as_ref()
            .and_then(|p| p.env_dict().ok())
            .map(|e| normalize(&Value::Map(e.into_iter().collect()), &reps))
            .unwrap_or(Value::Null);
        let sort = |v: &Value| -> Vec<(String, String)> {
            let mut items: Vec<(String, String)> = v
                .as_map()
                .map(|m| m.iter().map(|(k, x)| (k.clone(), jstr(x))).collect())
                .unwrap_or_default();
            items.sort();
            items
        };
        let (e, g) = (sort(exp_env), sort(&got_env));
        let diff: Vec<String> = e
            .iter()
            .filter(|x| !g.contains(x))
            .map(|x| format!("python {x:?}"))
            .chain(
                g.iter()
                    .filter(|x| !e.contains(x))
                    .map(|x| format!("rust   {x:?}")),
            )
            .collect();
        check("env", diff.is_empty(), diff.join("\n"));
    }

    // Defined pipes.
    let exp_meta = get(run, "pipes_meta");
    let got_meta = out
        .pipes_meta
        .as_ref()
        .map(|m| {
            normalize(
                &Value::List(m.iter().cloned().map(Value::Map).collect()),
                &reps,
            )
        })
        .unwrap_or(Value::Null);
    check(
        "pipes_meta",
        jstr(exp_meta) == jstr(&got_meta),
        format!(
            "  python: {}\n  rust:   {}",
            jstr(exp_meta),
            jstr(&got_meta)
        ),
    );
    let exp_pipes = get(run, "pipes");
    let got_pipes = out
        .pipes
        .as_ref()
        .map(|ps| {
            Value::List(
                ps.iter()
                    .map(|p| {
                        let mut m = Map::new();
                        m.insert("str".into(), Value::Str(p.to_string()));
                        m.insert("connector_keys".into(), p.connector_keys().into());
                        m.insert("metric_key".into(), p.metric_key().into());
                        m.insert(
                            "location_key".into(),
                            p.location_key().map(String::from).into(),
                        );
                        m.insert("instance_keys".into(), p.instance_keys().into());
                        m.insert("temporary".into(), p.temporary.into());
                        m.insert("parameters".into(), Value::Map(p.raw_parameters().clone()));
                        Value::Map(m)
                    })
                    .collect(),
            )
        })
        .unwrap_or(Value::Null);
    check(
        "pipes",
        jstr(exp_pipes) == jstr(&got_pipes),
        format!(
            "  python: {}\n  rust:   {}",
            jstr(exp_pipes),
            jstr(&got_pipes)
        ),
    );

    // Explain text.
    if let Value::Str(exp) = get(run, "explain") {
        let got = out.explain.clone().unwrap_or_default();
        let got = normalize_str(&got, &reps);
        if *exp != got {
            let exp_lines: Vec<&str> = exp.lines().collect();
            let got_lines: Vec<&str> = got.lines().collect();
            let first = exp_lines
                .iter()
                .zip(&got_lines)
                .position(|(a, b)| a != b)
                .unwrap_or(exp_lines.len().min(got_lines.len()));
            check(
                "explain",
                false,
                format!(
                    "first differing line {first}:\n  python: {:?}\n  rust:   {:?}\n--- python ---\n{exp}\n--- rust ---\n{got}",
                    exp_lines.get(first),
                    got_lines.get(first)
                ),
            );
        }
    }

    // Written files.
    if let Some(Value::Map(files)) = run.get("written_files") {
        for (fname, text) in files {
            let got = out
                .written_files
                .iter()
                .find(|(p, _)| {
                    p.file_name().map(|n| n.to_string_lossy() == fname.as_str()) == Some(true)
                })
                .map(|(_, t)| t.clone());
            check(
                &format!("written file {fname}"),
                got.as_deref() == Some(py_str(text).as_str()),
                format!("  python: {:?}\n  rust:   {got:?}", py_str(text)),
            );
        }
    }
    failures
}

#[test]
fn compose_parity_with_python() {
    let dir = fixtures().join("expected");
    let mut names: Vec<String> = std::fs::read_dir(&dir)
        .unwrap()
        .filter_map(Result::ok)
        .map(|e| e.file_name().to_string_lossy().to_string())
        .filter(|n| n.ends_with(".json"))
        .collect();
    names.sort();
    assert!(!names.is_empty(), "no fixtures in {}", dir.display());
    let only = std::env::var("COMPOSE_PARITY_ONLY").ok();
    let mut failures = Vec::new();
    let mut count = 0;
    for file in names {
        let name = file.trim_end_matches(".json").to_string();
        if only.as_deref().is_some_and(|o| !name.starts_with(o)) {
            continue;
        }
        let text = std::fs::read_to_string(dir.join(&file)).unwrap();
        let expected = Value::from_json_str(&text).unwrap();
        for (ix, run) in get(&expected, "runs").as_list().unwrap().iter().enumerate() {
            count += 1;
            failures.extend(run_case(&name, &expected, ix, run));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {count} runs differ:\n\n{}",
        failures.len(),
        failures.join("\n\n")
    );
}
